<span class="line"><span style="--shiki-light:#383A42;--shiki-dark:#C678DD;">mov</span><span style="--shiki-light:#383A42;--shiki-dark:#ABB2BF;"> x29, </span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">sp</span></span>
